// =====================================================
// 🛡️ SOLUCIÓN ROBUSTA PARA MENSAGES "USE TOOLS"
// =====================================================
// 1. Priorizar 'text' (respuesta limpia del agente)
// 2. Si no existe, usar 'output' pero filtrar tool calls
// 3. Múltiples patrones de regex para máximo robustez
// =====================================================

let respuestaIA = $input.first().json.text || $input.first().json.output || '';

// FILTRADO ROBUSTO DE TOOL CALLS
if (respuestaIA && respuestaIA.includes('Used tools')) {
    // Patrón 1: "[Used tools: Tool: X, Input: Y, Result: Z]"
    respuestaIA = respuestaIA.replace(/\[Used tools:[^\]]*\]\s*/gi, '');

    // Patrón 2: "Tool: TOOLNAME, Input: {...}, Result: {...}"
    respuestaIA = respuestaIA.replace(/Tool:\s*[A-Z_]+,\s*Input:\s*\{[^}]*\},\s*Result:/gi, '');

    // Patrón 3: "[Tool: ...]"
    respuestaIA = respuestaIA.replace(/\[Tool:[^\]]*\]\s*/gi, '');

    // Patrón 4: "Using tools:" o similar
    respuestaIA = respuestaIA.replace(/(?:Using|Used)\s+tools?:[^\n]*/gi, '');

    // Patrón 5: Eliminar brackets vacíos o con solo comas que quedan
    respuestaIA = respuestaIA.replace(/^\s*[\[\]\{\}\,]+\s*/m, '');

    // Patrón 6: Limpiar saltos de línea múltiples después de eliminar tool calls
    respuestaIA = respuestaIA.replace(/\n{3,}/g, '\n\n');

    respuestaIA = respuestaIA.trim();
}

// =====================================================
// 🧠 CONTINÚA CON EL RESTO DEL CÓDIGO ORIGINAL
// =====================================================

const contexto = $('4. Merge Datos + Productos').first().json;

// =====================================================
// 🔧 LIMPIEZA DEL MENSAJE (MANTENIENDO EMOJIS)
// =====================================================

let mensaje = respuestaIA || '';

// 1. ELIMINAR ASTERISCOS (negritas causan problemas)
mensaje = mensaje.replace(/\*/g, '');

// 2. CONVERTIR \n LITERAL A SALTO DE LÍNEA REAL
const BACKSLASH = String.fromCharCode(92);
const LITERAL_N = BACKSLASH + 'n';

let intentos = 0;
while (mensaje.indexOf(LITERAL_N) !== -1 && intentos < 50) {
    mensaje = mensaje.split(LITERAL_N).join('\n');
    intentos++;
}

// 3. LIMPIAR SOLO emojis rotos (unicode suelto) - MANTENER EMOJIS NORMALES
mensaje = mensaje.replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])/g, '');
mensaje = mensaje.replace(/(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, '');
mensaje = mensaje.replace(/\\u[0-9a-fA-F]{4}/g, '');

// 4. NO ELIMINAR EMOJIS - Los emojis son importantes para el tono amigable
// Solo eliminar flechas → y reemplazar por caracteres seguros
mensaje = mensaje.replace(/→/g, '•');

// 5. LIMPIAR ESPACIOS Y SALTOS EXCESIVOS
mensaje = mensaje.replace(/\n{3,}/g, '\n\n');
mensaje = mensaje.replace(/  +/g, ' ');
mensaje = mensaje.trim();

// 6. FALLBACK
if (!mensaje) {
    mensaje = '¡Hola! 😊 ¿En qué puedo ayudarte?';
