const contexto = $('4. Merge Datos + Productos').first().json;
const respuestaIA = $input.first().json.text || $input.first().json.output || '';
let mensaje = String(respuestaIA || '').replace(/\*/g, '').trim();
const nombreCompleto = String(contexto.clienteNombre || '').trim();
const tieneNombreCompleto = nombreCompleto.split(/\s+/).filter(Boolean).length >= 2;
const tieneDireccion = String(contexto.clienteDireccion || '').trim().length > 5;
const carrito = Array.isArray(contexto.clienteCarrito) ? contexto.clienteCarrito : [];
const pareceResumen = /subtotal|total:|resumen/i.test(mensaje);
if (pareceResumen && carrito.length > 0 && (!tieneNombreCompleto || !tieneDireccion)) {
  mensaje = '¡Casi listo! Para coordinar el envío, por favor confírmame tu nombre completo y la dirección de entrega.';
}
if (!mensaje) return [];
return [{ json: { from: contexto.to, to: contexto.from, type: 'text', text: { body: mensaje, preview_url: false } } }];

const termino = $fromAI('termino_busqueda', 'Producto o término a buscar en la tienda online', 'string');
const API_KEY = '4d8cfb14fba5451c875ac515fa047f9b';

if (!termino || !String(termino).trim()) {
  return '⚠️ Debes enviar un término de búsqueda válido.';
}

if (API_KEY === 'CONFIGURAR_AQUI_NUEVA_AGENT_OPS_API_KEY') {
  return '⚠️ Configura la nueva AGENT_OPS_API_KEY dentro del nodo TOOL_BuscarProductos antes de usar esta herramienta.';
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://tus-aguacates.vercel.app/api/agent/products',
    qs: { search: termino, limit: 5, active_only: true },
    headers: {
      'x-agent-key': API_KEY,
      'Accept': 'application/json'
    },
    json: true
  });

  return JSON.stringify(response);
} catch (error) {
  return '❌ Error consultando catálogo online: ' + error.message;
}

let phone = $fromAI('phone', 'Teléfono completo del cliente o últimos 10 dígitos. Si no se indica, se usa el teléfono del chat actual.', 'string');
const chatPhone = $('1. Pre-procesamiento YCloud').first().json.from || '';
const API_KEY = '4d8cfb14fba5451c875ac515fa047f9b';

if (!phone || !String(phone).trim()) {
  phone = chatPhone;
}

if (!phone || String(phone).replace(/\D/g, '').length < 10) {
  return JSON.stringify({
    success: false,
    error: {
      code: 'VALIDATION_ERROR',
      message: 'Phone must contain at least 10 digits'
    }
  });
}

if (API_KEY === 'CONFIGURAR_AQUI_NUEVA_AGENT_OPS_API_KEY') {
  return '⚠️ Configura la nueva AGENT_OPS_API_KEY dentro del nodo TOOL_ConsultarEstadoPedido antes de usar esta herramienta.';
}

try {
  const response = await this.helpers.httpRequest({
