// Obtener el producto de la consulta
const producto = $input.first().json;
// Obtener el contexto del preprocesamiento
const contexto = $('1. Pre-procesamiento YCloud').first().json;
// Formatear producto al formato esperado
const productoFormateado = {
  producto_id: producto.id,
  producto_nombre: producto.name,
  name: producto.name,
  id: producto.id,
