    productosEncontrados: [productoFormateado],
    productosTexto: `Producto del botón: ${producto.name} - $${Number(producto.price).toLocaleString('es-CO')}`
  }
};

const telefono = $fromAI('telefono', 'Teléfono del cliente (últimos dígitos)', 'string');

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://dep-n8n.n8ntusaguacates.space/webhook/confirmar-prepedido',
    headers: { 'Content-Type': 'application/json' },
    body: { telefono }
  });

  if (response.success) {
    return '✅ Pedido confirmado! ID: ' + (response.order_id || 'N/A') + ', Total: $' + (response.total || 0);
  } else {
    return '❌ ' + (response.message || 'No se encontró pre-pedido');
  }
} catch (error) {
  return '❌ Error: ' + error.message;
}

// =====================================================
// 🛡️ SOLUCIÓN ROBUSTA PARA MENSAGES "USE TOOLS"
// =====================================================
// 1. Priorizar 'text' (respuesta limpia del agente)
// 2. Si no existe, usar 'output' pero filtrar tool calls
// 3. Múltiples patrones de regex para máximo robustez
// =====================================================

let respuestaIA = $input.first().json.text || $input.first().json.output || '';

// FILTRADO ROBUSTO DE TOOL CALLS
if (respuestaIA && respuestaIA.includes('Used tools')) {
    // Patrón 1: "[Used tools: Tool: X, Input: Y, Result: Z]"
    respuestaIA = respuestaIA.replace(/\[Used tools:[^\]]*\]\s*/gi, '');

    // Patrón 2: "Tool: TOOLNAME, Input: {...}, Result: {...}"
    respuestaIA = respuestaIA.replace(/Tool:\s*[A-Z_]+,\s*Input:\s*\{[^}]*\},\s*Result:/gi, '');

    // Patrón 3: "[Tool: ...]"
    respuestaIA = respuestaIA.replace(/\[Tool:[^\]]*\]\s*/gi, '');

    // Patrón 4: "Using tools:" o similar
    respuestaIA = respuestaIA.replace(/(?:Using|Used)\s+tools?:[^\n]*/gi, '');

    // Patrón 5: Eliminar brackets vacíos o con solo comas que quedan
    respuestaIA = respuestaIA.replace(/^\s*[\[\]\{\}\,]+\s*/m, '');

    // Patrón 6: Limpiar saltos de línea múltiples después de eliminar tool calls
    respuestaIA = respuestaIA.replace(/\n{3,}/g, '\n\n');

    respuestaIA = respuestaIA.trim();
}

// =====================================================
// 🧠 CONTINÚA CON EL RESTO DEL CÓDIGO ORIGINAL
// =====================================================

const contexto = $('4. Merge Datos + Productos').first().json;

// =====================================================
// 🔧 LIMPIEZA DEL MENSAJE (MANTENIENDO EMOJIS)
// =====================================================

let mensaje = respuestaIA || '';

// 1. ELIMINAR ASTERISCOS (negritas causan problemas)
mensaje = mensaje.replace(/\*/g, '');

// 2. CONVERTIR \n LITERAL A SALTO DE LÍNEA REAL
const BACKSLASH = String.fromCharCode(92);
const LITERAL_N = BACKSLASH + 'n';

let intentos = 0;
while (mensaje.indexOf(LITERAL_N) !== -1 && intentos < 50) {
    mensaje = mensaje.split(LITERAL_N).join('\n');
    intentos++;
}

// 3. LIMPIAR SOLO emojis rotos (unicode suelto) - MANTENER EMOJIS NORMALES
mensaje = mensaje.replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])/g, '');
mensaje = mensaje.replace(/(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, '');
mensaje = mensaje.replace(/\\u[0-9a-fA-F]{4}/g, '');

// 4. NO ELIMINAR EMOJIS - Los emojis son importantes para el tono amigable
// Solo eliminar flechas → y reemplazar por caracteres seguros
mensaje = mensaje.replace(/→/g, '•');

// 5. LIMPIAR ESPACIOS Y SALTOS EXCESIVOS
mensaje = mensaje.replace(/\n{3,}/g, '\n\n');
mensaje = mensaje.replace(/  +/g, ' ');
mensaje = mensaje.trim();

// 6. FALLBACK
if (!mensaje) {
    mensaje = '¡Hola! 😊 ¿En qué puedo ayudarte?';
}

// =====================================================
// 🔗 DETECTAR SI HAY URLs PARA HABILITAR PREVIEW
// =====================================================
const tieneUrl = mensaje.includes('http://') || mensaje.includes('https://') || mensaje.includes('tus-aguacates.vercel.app');

// =====================================================
// 🖼️ PREPARAR IMAGEN SI HAY PRODUCTOS
// =====================================================

const prods = contexto.productosEncontrados || [];
let img = null;
if (prods.length > 0) {
    const p = prods.find(x => x.main_image_url && x.main_image_url.length > 0);
    if (p) {
        let url = p.main_image_url;
        if (url.includes('supabase.co/storage') && url.includes('.webp')) {
            url = url.replace('/object/public/', '/render/image/public/') + '?format=origin';
        }
        img = {
            url,
            nombre: p.name,
            precio: p.price,
            caption: p.name + ' - $' + Number(p.price).toLocaleString('es-CO')
        };
    }
}

// =====================================================
// 📤 PREPARAR RESPUESTAS PARA YCLOUD
// =====================================================

const resultados = [];

// Agregar imagen si existe
if (img && !contexto.esMedia) {
    resultados.push({
        json: {
            from: contexto.to,
            to: contexto.from,
            type: 'image',
            image: {
                link: img.url,
                caption: img.caption
            }
        }
    });
}

// Agregar mensaje de texto CON preview_url si hay links
const mensajeJson = {
    from: contexto.to,
    to: contexto.from,
    type: 'text',
    text: { 
        body: mensaje,
        preview_url: tieneUrl  // Habilita Link Preview cuando hay URLs
    }
};

resultados.push({ json: mensajeJson });

return resultados;

// TOOL: Confirmar Pedido + Etiqueta YCloud
const telefono = $('1. Pre-procesamiento YCloud').first().json.from;

try {
  // Usar httpRequestWithAuthentication en lugar de httpRequest + credentials manual
  const updateResult = await this.helpers.httpRequestWithAuthentication.call(this, 'YCloudApi', {
    method: 'POST',
    url: 'https://api.ycloud.com/v2/contacts',
    body: {
      phoneNumber: '+' + telefono,
      tags: ['Confirmado']
    },
    json: true
  });

  return 'Cliente ' + telefono + ' etiquetado como Confirmado en YCloud. Continúa con TOOL_CambiarEstadoCliente para cambiar el estado a PEDIDO_CONFIRMADO.';

} catch (e) {
  return 'Error al etiquetar: ' + e.message + '. Continúa con TOOL_CambiarEstadoCliente para cambiar estado a PEDIDO_CONFIRMADO.';
}

